import sys; sys.path.insert(0, "Tools/prd_ledger/89")
from _lib import c, table, save

c(13, "§3.1 table (verbatim); §3.1", "insight", "The prioritised picture (verbatim): " + table("## 3.1 The prioritised picture", 0) + " — four findings carry the corpus: the paywall (paywall_any 107, 42.29%) is the largest negative theme by a factor of five and explains 90.14% of one-star reviews; trust, not only price (trust_breach 42 > value_objection 33); the core is liked (simplicity 81, praise_specific 98 / 38.74%); buyers have a different problem (paid_problem 16 / 6.32% — restore and data loss, concentrated before 2026).", "n/a", "mixed", "paywall_any 107; trust_breach 42; value_objection 33; simplicity 81; paid_problem 16; negative_any 139 (54.94%); praise_any 150 (59.29%)", "none", "table", "generalisable", ["12583373249", "12787415461"], "", "")

c(14, "§3.2 table (verbatim); §3.2", "anti-pattern", "The paywall codes (verbatim): " + table("## 3.2 The paywall", 0) + " — the wall arrives after the reviewer has invested: install, log for days, then lose the ability to tick a box (TRIAL_WALL 73 / 28.85%): 'Works great the first weeK. After the free trial ends, even the basic function of checking off 1 day is behind a paywall'; 'it says you have to pay 6 dollars after I already did a lot of stuff with the app'; 'after about two weeks it suddenly became unusable and asked for payment. I wanted to be told from the start that it was a trial' (jp, translated); non-disclosure is the aggravating factor — PAY_UNDISCLOSED 27, 26 of whom also describe the wall ('Upon installation it says nothing about a free trial period'; 'NOT A SINLGE WORD was said about the need to pay'); fraud language follows (SCAM 18, 1.61★: 'Money grubbing scammers', 'textbook bait and switch tactic', 'una estafa'); locked records hurt most (DATA_LOCKED 8: 'Now I can't get back what I wrote down'; 'now I can't even see the information I entered in those 7 days' — 'this matters more for a medication tracker than for a to-do list'); stated loss — lost_user_signal 27: CHURN_STATED 13, WARN_OTHERS 14.", "trial wall after investment; not disclosed; records locked", "1★-burst", "TRIAL_WALL 73 / 28.85%; UNDISCLOSED 27 (26 with wall); SCAM 18 / 1.61★; DATA_LOCKED 8; CHURN 13; WARN 14", "dont", "High-priority", "generalisable", ["12583373249", "14249597998", "10815980713", "11361427540", "12163557097", "14347811446", "11545639546", "11756829140", "13953491590", "11667422038", "12183886855"], "", "")

c(15, "§3.2 (price objections; free substitutes; before the trial wall)", "insight", "Price objections are about simplicity, not the number: PAY_NOT_WORTH 28 (11.07%, 1.71★) — almost always that ticking a calendar should not cost money ('Why would using a calendar cost money? You can do this for free on your iPhone'; 'too simple to pay 90 pesos', mx, translated), only one argues a lower number ('a couple of hundred roubles would be about right'); free substitutes named — COMP_FREE_ALTERNATIVE 9 (3.56%, 1.11★): a physical calendar, the phone's default calendar, Google Calendar, a paper diary, other free apps, and building one with an AI assistant ('Uninstalled this and created my own in 10 mins with Claude', 2026-07-29); before the trial wall (2022–2023) the complaints were freemium-shaped — two free calendars only (CALENDAR_LIMIT 3), dark mode moved behind payment and 'previous free features into paid ones'; PAY_FEATURE_REVERSAL 7 (2.77%) also covers users locked out after long free use — 'Used this app around last year and it worked great, the premium features makes sense like more tabs, and more customization. But recently… now you need to pay for the WHOLE features'.", "whole core moved from freemium to trial-gated", "complaint", "NOT_WORTH 28 / 11.07%; FREE_ALTERNATIVE 9 / 1.11★; CALENDAR_LIMIT 3; FEATURE_REVERSAL 7", "product-rule", "High-priority", "generalisable", ["13627694926", "13315450144", "12716103218", "11282003485", "13021233018", "13657817683", "13989810360", "14362887124", "8685787447", "8746219852", "12995883665"], "a calendar-shaped product invites comparison with free calendars — the argument is never about the amount", "")

c(16, "§3.3 table (verbatim); §3.3", "monetization", "Price acceptance, ads and the missing free tier (verbatim): " + table("## 3.3 Price acceptance", 0) + " — U:price_positive 20 (7.91%, 4.60★), 15 of whom do not say they bought; the price is small (PRICE_FAIR 14: 'it's one-time $4, people! A cup of coffee!'; 'compared to others that are similar in quality it is by far the cheapest') and it is paid once (PAY_ONCE_PRAISE 10: 'really great that payment is one-time', ru, translated; 'an ad-free version for a few bucks without subscription!'); conditional willingness (PAY_CONDITIONAL_WILLING 6, 5 in Japan) — disclosure, a widget, or paid extras rather than a paid base; the subscription misunderstanding (PAY_SUBSCRIPTION_BELIEF 5: '$4/month', 'Unless you purchase a subscription') — the listing sells only a one-time item and believers rate it 2.20★; ads — U:ads_any 11 (4.35%), ADS_COMPLAINT 5 all 2022-05 → 2024-10, two from buyers who still saw ads; two ask for an ad-supported free version instead of the wall ('You could just show ads so that we can use it freely'), two say it is free with no ads, three use the free version — the corpus cannot tell whether a working ad-supported tier exists; Android — PLATFORM_PRICE_GAP 2 (both Jan 2026): 'Why is the iPhone app paid? And only gives you a week-long trial, while it's free on Android?'.", "one-time $4.99; ad tier unclear; free on Android", "purchase-driver", "price_positive 20 / 7.91% / 4.60★; PRICE_FAIR 14; PAY_ONCE 10; CONDITIONAL 6; SUBSCRIPTION_BELIEF 5 / 2.20★; ads_any 11; PLATFORM_GAP 2", "do", "High-priority", "generalisable", ["12398233280", "13970851584", "12470755467", "12104603863", "13487151159", "10792547110", "7684285778", "13540676316", "8669998205", "9690318266", "10818815408", "13123238983", "12138106398", "14203023679", "13689050772", "13584852727"], "", "a reviewer who wrongly believes a one-time price is a subscription rates it two stars lower")

c(17, "§3.4 table (verbatim); §3.4", "feature", "What people praise (verbatim): " + table("## 3.4 What people praise", 0) + " — praise_any 150 (59.29%), praise_specific 98 (38.74%); simplicity is the product (PRAISE_SIMPLE 54, PRAISE_EASE 49), framed against other apps: 'It's perfect because it's simple. All the other apps have a bunch of functions and distractions'; 'among apps with lots of unnecessary features, this one is very simple and easy to use' (jp, translated); 'simple and not cluttered with too many options'; fit (NEED_FIT 31, 4.65★: 'Finally a calendar app where you can check off days' — 11 of 31 American, one Japanese); the calendar mechanics (calendar_core 25, 4.72★: one-tap 7, one calendar per habit 11, month at a glance 11, editing past days 1 — 'having a visual where I can see how often I accomplish my goals in a given month is helpful'); personalisation (CUSTOMISE 10, emojis above all: 'I made it a cute emoji I like, got motivated and kept at it every day', jp, translated); motivation 6; haptic 1 ('I fell addicted to the little haptic click every time i would click off another day clean… it's a shame i have to get rid of the app now', 2★); generic praise 42 name no quality.", "simplicity as the product; emoji marks; month grid", "praise", "SIMPLE 54 / 21.34%; EASE 49; NEED_FIT 31 / 4.65★; MULTI_CALENDAR 11 / 5.00★; MONTH_VIEW 11 / 4.91★; CUSTOMISE 10; ONE_TAP 7; HAPTIC 1", "must-have", "High-priority", "generalisable", ["12787415461", "9543307410", "13309279905", "11415934537", "12023528527", "11573514540", "13689293377", "11817411885"], "", "")

c(18, "§3.5 table (verbatim); §3.5", "audience", "Use cases and outcomes (verbatim): " + table("## 3.5 Use cases and outcomes", 0) + " — use_case_any 32 (12.65%, 4.44★): fitness 18 (gym attendance, swimming, stretching, strength training); health 14 (medication, insulin, supplements, diet, bowel movements — 7 of 14 Japanese); other 4 (work attendance, homestay bookings, piano practice); outcomes OUT_BENEFIT 9 ('with the app I don't forget my pills', mx, translated; a Japanese buyer reached a diet goal and came back for exercise); long-term USE_LONG_TERM 4 ('using the app for over two years'), two of whom are paid users whose long use ended in a restore failure; ACQ_TRIED_MANY 8 (4.50★); the trial wall lands on exactly these uses — 'I installed it so I wouldn't forget my supplements, but it was usable for only 7 days' (jp, translated).", "n/a", "mixed", "use_case 32 / 12.65%; FITNESS 18; HEALTH 14 (jp 7); OUT_BENEFIT 9; LONG_TERM 4; TRIED_MANY 8", "none", "High-priority", "generalisable", ["10359288853", "12145951974", "13635728301", "10139655335", "10498260582", "11129150989", "13450700291", "14474985024", "14195716095", "14416581730", "14105625927", "10307647024", "12486925913"], "", "")

c(19, "§3.6 table (verbatim); §3.6", "do", "The developer relationship (verbatim): " + table("## 3.6 The developer relationship", 0) + " — dev_positive 20 (7.91%) vs dev_negative 5 (1.98%); thanks (PRAISE_DEV_THANKS 19, 4.58★: 'Thank you to the developer for opting for simplicity!'); shipped requests noticed (DEV_IMPROVEMENT_NOTICED 3: 'I sent feedback to the developer to ask for one change: to be able to adjust the period displayed in the graph. And today I looked at the update, and it's done!'); unkept promises (DEV_PROMISE_UNKEPT 3, all Japanese, all from 2025-06-15 onward); no response (SUPPORT_UNRESPONSIVE 2: 'no way to contact support'; 'Lodged a support ticket- no answer'); questions posted as reviews (SUPPORT_QUESTION 5), three of them paid users asking how to restore or use their purchase on another device.", "solo developer ships small requests; no support channel for restore", "praise", "DEV_THANKS 19 / 7.51%; IMPROVEMENT_NOTICED 3; PROMISE_UNKEPT 3; UNRESPONSIVE 2; SUPPORT_QUESTION 5", "do", "High-priority", "generalisable", ["13487151159", "12398233280", "10465840832", "12486925913", "8943842333", "12598179708"], "", "a visibly shipped feedback request is written up as a five-star review")

c(20, "§3.7 table (verbatim); §3.7", "feature", "Requests (verbatim): " + table("## 3.7 Requests", 0) + " — request_any 39 (15.42%, 4.18★), 16 of 39 from four-star reviewers; more customisation (REQ_CUSTOMISATION 9: tab colours, background colour, all emojis, per-date emoji, cell line thickness, filled cells, hiding last month's faded checks — several now in the listing); widgets 5 (2022-01 → 2025-01) and notifications 5 (2021-08 → 2025-08) — both now in the listing, neither request recurs after; REQ_WIDGET_MULTI 1 (2026-07-20) asks to tick several habits from the widget; reports (REQ_REPORT_OPTIONS 5: all-time or three-year ranges, y-axis from zero, graphs, percentages); count by mark (REPORT_ALL_MARKS_COUNTED 4 — a ❌ day counts as done; two paid, one gave one star for it, one wonders whether paying 600円 was a mistake); sync across devices 3 (developer replied 2025-02-10 it is being 'actively' looked into); one each: several habits in one view (2), numeric values per day, repeat an entry across days, calendar folders, reset records, haptics, images, Arabic, a Huawei version, iPad landscape, merging with the developer's other app, non-cloud export.", "n/a", "request", "request_any 39 / 15.42%; CUSTOMISATION 9; WIDGET 5; NOTIFICATIONS 5; REPORT_OPTIONS 5; ALL_MARKS_COUNTED 4; SYNC 3; MULTI_HABIT_VIEW 2", "must-have", "High-priority", "generalisable", ["7722322287", "7684285778", "10284447344", "9288474088", "13192396823", "12758921006", "11360924116", "14327295455", "12727889673", "13782987039", "11759516789", "8879126451", "12710720903", "10775717295", "13644913370", "11126142010", "11592600279", "12662245100", "13013380155", "13313149397", "11129150989", "13241795264", "10790606920", "12643442076", "14119601087", "12339505669", "8670254714", "11574826369", "11449760821"], "", "")

c(21, "§3.8 table (verbatim); §3.8 every-defect table (verbatim); §3.8; §3.9 table (verbatim); §3.9", "must-never-break", "Defects and friction outside the paywall (verbatim): " + table("## 3.8 Defects and friction", 0) + " || every one (verbatim): " + table("## 3.8 Defects and friction", 1) + " — defect_non_payment 14 (5.53%, 3.14★); two patterns: the record is not always right — counts that don't add up (2025-11, 2026-03), checks that vanish on reopening (2026-07), notes that fail (2024-01, two on consecutive days, one naming version 10.1.0, coinciding with the first trial-wall reviews), a date that doesn't roll over unless the app is closed, a check that cannot be erased, a future date checked by accident, a mis-tap confirmation that appears too often — record_integrity 20 (7.91%) once data loss and locked records are included; and nine of the fourteen are Japanese; REVIEW_PROMPT_EXCESS 1 ('a review request every day, very excessive', br, translated) is recorded because it bears on the rating gap — if the prompt fires daily it would help explain 7,065 mostly five-star ratings beside 253 mostly critical texts, but one review cannot establish that. Privacy (verbatim): " + table("## 3.9 Privacy", 0) + " — one concern; no review mentions tracking, analytics or third parties.", "counts, checks and notes occasionally wrong; date stale until relaunch", "complaint", "defect_non_payment 14 / 5.53% (jp 9); COUNT_WRONG 2; NOTES_ERROR 2; CHECK_LOST 1; DATE_STALE 1; FRICTION_CHECK_INPUT 3; REVIEW_PROMPT_EXCESS 1; PRIV 1", "must-never-break", "High-priority", "generalisable", ["7677254284", "8091656228", "8746219852", "10300583061", "10833631248", "10836719873", "10869463865", "12486925913", "12722215871", "13410320941", "13800362190", "14112073954", "14270574717", "14513815810", "11449760821"], "", "")

c(22, "§4.1 table (verbatim); §4.1; §4.2 table (verbatim); §4.2", "data-caveat", "Distribution (verbatim): " + table("## 4.1 The distribution", 0) + " — mean 3.332★, median 4★, bimodal (110 five-star, 71 one-star, 72 between) vs public 4.676★; themes by band (verbatim): " + table("## 4.2 Themes by star band", 0) + " — 'the bands are different in kind': paywall share rises from 5% of five-star to 90% of one-star, specific praise falls from 60% to 3%; four-star is the requests band (62%); three-star holds the largest share of paid users (31%) and post-purchase problems (27%).", "n/a", "mixed", "5★ 110 (43.48%); 1★ 71 (28.06%); public 4.676★", "none", "table", "generalisable", ["13353478605"], "", "")

c(23, "§4.3; §4.4; §4.5; §4.6; §4.6 table (verbatim)", "data-caveat", "By band: 5★ (110) — 98 praise, 66 name a quality, 55 simplicity; fit and use cases are five-star themes (26 of 31 NEED_FIT, 26 of 32 use_case); 15 of 20 price-positive are five-star — the one-time price is part of what earns the top rating; 41 under 60 characters; 6 carry a paywall code and 7 are contradictions; 4★ (26) — 'Good, and please add…': 16 of 26 carry a request (62%), 21 praise ('tap the date and it's marked. But where is the widget? …so only 4 points', ru, translated), six mild paywall codes (a Japanese reviewer calls the one-time purchase 'a good deal' while saying the trial should be stated up front); 3★ (26) — the paid-user band: 8 explicit buyers, 7 post-purchase problems (restore failures 5, ads after purchase, a refund request), 15 paywall, 17 also praise ('Its good and pretty basic but the 3 stars cuz I can't restore the purchase and no way to contact support'); 2★ (20) — 16 paywall, 8 trust-breach; the four without a paywall code are buyer problems or record defects; 1★ (71) — 64 paywall (90.14%), only 5 contain any praise; the seven without a paywall code (verbatim): " + table("## 4.6 Two- and one-star reviews", 0) + " — four of the seven are paid users: 'outside the paywall, what earns one star is losing, miscounting or being re-charged for records the user paid to keep'.", "n/a", "mixed", "4★ requests 62%; 3★ buyers 8 of 26; 1★ paywall 90.14%; 1★ non-paywall 7 (4 paid)", "none", "table", "generalisable", ["11950112016", "11777550164", "10465840832", "8943842333", "10307647024", "10815164113", "12598179708", "8669998205", "10628286567", "9690318266", "11126142010", "13410320941", "14270574717", "10355887642", "10775717295", "10789194783", "10836719873", "10850910296", "11804387968", "14513815810"], "", "")

c(24, "§4.7 table (verbatim); §4.7", "contradiction", "Rating-versus-text contradictions (verbatim): " + table("## 4.7 Rating-versus-text contradictions", 0) + " — META_RATING_TEXT_MISMATCH 10 (3.95%), retained at the star given; seven of the ten are five-star reviews with negative text ('(1 STAR RATING) DO NOT INSTALL THIS' at 5★; 'Scammed out of current subscription' at 5★; 'Was a good app until they became money hungry' at 5★) — 'some reviewers appear to tap five stars and then write a complaint, which is consistent with the review-prompt question in §8.7 but does not establish it'.", "n/a", "mixed", "MISMATCH 10 / 3.95%; 5★ with negative text 7", "none", "Very strong", "generalisable", ["11453384232", "11736707357", "12407538365", "12486925913", "12565196462", "13098699650", "13157323803", "13353478605", "13386904366", "13644913370"], "", "")

